@prefix dct: <http://purl.org/dc/terms/> .
@prefix mlm: <https://w3id.org/ogc/stac/mlm/> .
@prefix prov: <http://www.w3.org/ns/prov#> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode <https://example.org/test/IncompleteRun> ;
            sh:resultMessage "Node ex:IncompleteRun->prov:used does not contain a value in the set: ['<https://hirondelle.crim.ca/stac/collections/stac-mlm-examples/items/ogc-ospd2026-downscaling-unet>']" ;
            sh:resultPath prov:used ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraintComponent sh:HasValueConstraintComponent ;
            sh:sourceShape [ sh:hasValue <https://hirondelle.crim.ca/stac/collections/stac-mlm-examples/items/ogc-ospd2026-downscaling-unet> ;
                    sh:path prov:used ] ],
        [ a sh:ValidationResult ;
            sh:focusNode <https://example.org/test/IncompleteRun> ;
            sh:resultMessage "Node ex:IncompleteRun->dct:subject does not contain a value in the set: ['mlm:super-resolution']" ;
            sh:resultPath dct:subject ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraintComponent sh:HasValueConstraintComponent ;
            sh:sourceShape [ sh:hasValue mlm:super-resolution ;
                    sh:path dct:subject ] ],
        [ a sh:ValidationResult ;
            sh:focusNode <https://example.org/test/IncompleteRun> ;
            sh:resultMessage "Node ex:IncompleteRun->dct:subject does not contain a value in the set: ['mlm:downscaling']" ;
            sh:resultPath dct:subject ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraintComponent sh:HasValueConstraintComponent ;
            sh:sourceShape [ sh:hasValue mlm:downscaling ;
                    sh:path dct:subject ] ],
        [ a sh:ValidationResult ;
            sh:focusNode <https://example.org/test/IncompleteRun> ;
            sh:resultMessage "Node ex:IncompleteRun->dct:type does not contain a value in the set: ['<https://crim-ca.github.io/bblocks-process-profiles/def/activity-type/climate-downscaling-inference>']" ;
            sh:resultPath dct:type ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraintComponent sh:HasValueConstraintComponent ;
            sh:sourceShape [ sh:hasValue <https://crim-ca.github.io/bblocks-process-profiles/def/activity-type/climate-downscaling-inference> ;
                    sh:path dct:type ] ] .

